use crate::{ContextPacket, TaskSpec};
use serde::{Deserialize, Serialize};
use std::path::Path;

/// Agent-facing policy recommendation for a packet.
#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum InjectionRecommendation {
    InjectFull,
    InjectCompact,
    Abstain,
    NeedsTarget,
}

/// Bounded packet quality scores. Each field is in `0..=5`.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct PacketQualityScores {
    pub relevance: u8,
    pub completeness: u8,
    pub specificity: u8,
    pub freshness: u8,
    pub grounding: u8,
    pub concision: u8,
    pub noise_absence: u8,
}

impl PacketQualityScores {
    #[must_use]
    pub const fn high() -> Self {
        Self {
            relevance: 5,
            completeness: 5,
            specificity: 5,
            freshness: 5,
            grounding: 5,
            concision: 5,
            noise_absence: 5,
        }
    }

    #[must_use]
    pub fn average(&self) -> f64 {
        f64::from(
            self.relevance
                + self.completeness
                + self.specificity
                + self.freshness
                + self.grounding
                + self.concision
                + self.noise_absence,
        ) / 7.0
    }
}

